        if (zeit) facts.push(`${window.skIcon('uhr', 'hd-ic--xs')} ${zeit}`);
        if (daten.weight_grams) facts.push(`${window.skIcon('waage', 'hd-ic--xs')} ${Math.round(daten.weight_grams)} g`);
