                const checkAuthAndSetupPush = async () => {
                    const token = localStorage.getItem('access_token');
                    if (token) {
                        // Warte kurz bis alles geladen ist
                        setTimeout(() => {
                            this.setup();
                        }, 1000);
                    }
                };
                checkAuthAndSetupPush();
